import { initAudio, registerAudioAssets, setMasterVolume } from './audio.js';
import { loadSections, loadPlutoData } from './content.js';
import { render } from './pluto-model.js';
import { renderSections, setupScrollObserver } from './sections.js';

/**
 * @returns {Promise<void>}
 */
export async function init() {
  initAudio();
  registerAudioAssets([
    { id: 'sfx-hover', src: 'assets/sfx-hover.mp3', type: 'sfx' },
    { id: 'sfx-click', src: 'assets/sfx-click.mp3', type: 'sfx' },
    { id: 'sfx-overview', src: 'assets/sfx-overview.mp3', type: 'sfx' },
    { id: 'sfx-structure', src: 'assets/sfx-structure.mp3', type: 'sfx' },
    { id: 'sfx-orbit', src: 'assets/sfx-orbit.mp3', type: 'sfx' },
    { id: 'ambient-space', src: 'assets/ambient-space.mp3', type: 'ambient' }
  ]);

  const plutoConfig = loadPlutoData();
  const modelContainer = document.getElementById('pluto-model-container');
  if (modelContainer) {
    render(modelContainer, plutoConfig);
  }

  const sections = await loadSections();
  const sectionsContainer = document.getElementById('sections-container');
  if (sectionsContainer) {
    renderSections(sections, sectionsContainer);
    setupScrollObserver();
  }

  setupAudioControls();
}

function setupAudioControls() {
  const volumeButton = document.getElementById('master-volume');
  if (!volumeButton) return;
  let isMuted = false;
  volumeButton.addEventListener('click', () => {
    isMuted = !isMuted;
    if (isMuted) {
      setMasterVolume(0);
      volumeButton.textContent = '🔇';
      volumeButton.setAttribute('aria-label', 'Unmute');
    } else {
      setMasterVolume(1);
      volumeButton.textContent = '🔊';
      volumeButton.setAttribute('aria-label', 'Mute');
    }
  });
}

document.addEventListener('DOMContentLoaded', init);

:root {
  --bg-color: #0b0d17;
  --text-color: #e0e6ed;
  --accent-color: #00d4ff;
  --pluto-crust: #8b7355;
  --pluto-mantle: #5c4033;
  --pluto-core: #ff6b6b;
}

body {
  margin: 0;
  background: var(--bg-color);
  color: var(--text-color);
  font-family: 'Inter', system-ui, sans-serif;
  overflow-x: hidden;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
  background: rgba(11, 13, 23, 0.9);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 100;
}

main {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem;
}

#pluto-model-container {
  width: 100%;
  max-width: 800px;
  height: 60vh;
  margin-bottom: 2rem;
}

#sections-container {
  width: 100%;
  max-width: 800px;
}

.pluto-section {
  padding: 2rem;
  margin-bottom: 2rem;
  border-left: 4px solid var(--accent-color);
  background: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.pluto-section.visible {
  opacity: 1;
  transform: translateY(0);
}

@keyframes pluto-rotate {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes pluto-glow {
  0%, 100% { filter: drop-shadow(0 0 5px var(--accent-color)); }
  50% { filter: drop-shadow(0 0 20px var(--accent-color)); }
}

@keyframes pluto-layer-highlight {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 1; }
}

.pluto-model-svg {
  width: 100%;
  height: 100%;
  animation: pluto-rotate 60s linear infinite;
}

.pluto-model-svg.anim-active {
  animation: pluto-glow 2s ease-in-out infinite;
}

.pluto-layer {
  transition: opacity 0.3s ease, filter 0.3s ease;
}

.pluto-layer.highlighted {
  animation: pluto-layer-highlight 1.5s ease-in-out infinite;
  filter: drop-shadow(0 0 10px var(--accent-color));
}
